    else
      k[row * 128 + pair - 1024] = rotated;
  } else {
    v[row * 128 + pair - 1152] = __floats2bfloat162_rn(a0, a1);
  }
}

extern "C" int32_t pi05_qkv_prepare(
    const void* x, const void* scale, void* scaled, void* factor,
    int32_t rows, cudaStream_t stream) {
